command:
cat > /etc/nginx/conf.d/node1-https.conf <<'EOC'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1;

    ssl_certificate     /etc/pki/node1cert/fullchain.crt;
    ssl_certificate_key /etc/pki/node1cert/server.key;

    location / {
        return 200 "ok\n";
        add_header Content-Type text/plain;
    }
}
EOC
nginx -t
systemctl enable --now nginx
systemctl status nginx --no-pager | head -10

